(function(){const Q=[{"id": "q_doverennost-v-nalogovuyu", "c": "tax", "q": "Нужна ли доверенность бухгалтеру для налоговой?", "k": "нужна ли доверенность бухгалтеру для налоговой? да, если бухгалтер или другое лицо представляет организацию в налоговых отношениях — это уполномоченный представитель, и он действует на основании доверенности за подписью руководителя (или иного лица, уполномоченного уставом).", "a": "Да, если бухгалтер или другое лицо представляет организацию в налоговых отношениях — это уполномоченный представитель, и он действует на основании доверенности за подписью руководителя (или иного лица, уполномоченного уставом).<br><br><b>Пошагово:</b><ol><li>Оформите доверенность за подписью руководителя.</li><li>Перечислите в ней конкретные полномочия (подача деклараций, получение документов и т.д.).</li><li>Укажите срок действия.</li><li>Для электронного документооборота проверьте также ЭЦП и атрибутный сертификат.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Налоговый кодекс РБ (Общая часть) от 19.12.2002 № 166-З, ст. 24", "q": "Уполномоченный представитель плательщика-организации осуществляет свои полномочия на основании доверенности, выдаваемой за подписью ее руководителя или иного лица, уполномоченного на это ее учредительным документом.", "u": "https://pravo.by/document/?guid=3871&p0=hk0200166"}], "u": "/q/doverennost-v-nalogovuyu/", "d": null}, {"id": "q_elektronnyj-aukcion", "c": "zak", "q": "Что такое электронный аукцион в госзакупках и кто побеждает?", "k": "что такое электронный аукцион в госзакупках и кто побеждает? электронный аукцион — конкурентная процедура на электронной торговой площадке, в которой побеждает участник, предложивший наименьшую цену и соответствующий требованиям аукционных документов. применяется по перечню совмина и в иных случаях по решению заказчика.", "a": "Электронный аукцион — конкурентная процедура на электронной торговой площадке, в которой побеждает участник, предложивший наименьшую цену и соответствующий требованиям аукционных документов. Применяется по перечню Совмина и в иных случаях по решению заказчика.<br><br><b>Пошагово:</b><ol><li>Изучите аукционные документы и требования.</li><li>Подготовьте первую часть (техническую) и вторую (квалификационную) предложения.</li><li>Внесите аукционное обеспечение, если оно требуется.</li><li>Участвуйте в торгах на площадке в назначенное время.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 13.07.2012 № 419-З «О государственных закупках товаров (работ, услуг)», п. 1 ст. 38", "q": "Электронный аукцион – вид процедуры государственной закупки, представляющий собой гласный и конкурентный способ выбора поставщика (подрядчика, исполнителя) при осуществлении государственной закупки на электронной торговой площадке, при которой победителем признается участник, предложивший наименьшую цену по результатам торгов и соответствующий требованиям аукционных документов.", "u": "https://pravo.by/document/?guid=3871&p0=h11200419"}], "u": "/q/elektronnyj-aukcion/", "d": null}, {"id": "q_finansovaya-podderzhka-msp", "c": "sup", "q": "Какую финансовую поддержку может получить малый бизнес?", "k": "какую финансовую поддержку может получить малый бизнес? закон № 148-з предусматривает финансовую поддержку мсп, в том числе через белорусский фонд финансовой поддержки предпринимателей: финансовые средства на возвратной возмездной или безвозмездной основе, имущество в лизинг и др. конкретные программы и условия устанавливаются отдельными актами.", "a": "Закон № 148-З предусматривает финансовую поддержку МСП, в том числе через Белорусский фонд финансовой поддержки предпринимателей: финансовые средства на возвратной возмездной или безвозмездной основе, имущество в лизинг и др. Конкретные программы и условия устанавливаются отдельными актами.<br><br><b>Пошагово:</b><ol><li>Определите, к какой категории МСП вы относитесь.</li><li>Изучите действующие программы Белорусского фонда финансовой поддержки предпринимателей и местных исполкомов.</li><li>Подготовьте бизнес-план и документы по требованиям программы.</li><li>Если программа неясна — направьте письменный запрос в фонд или исполком (шаблон ниже).</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 01.07.2010 № 148-З «О поддержке малого и среднего предпринимательства», ст. 10", "q": "Белорусским фондом финансовой поддержки предпринимателей путем предоставления: финансовых средств на возвратной возмездной или безвозмездной основе; имущества на условиях финансовой аренды (лизинга); …", "u": "https://pravo.by/document/?guid=3871&p0=h11000148"}], "u": "/q/finansovaya-podderzhka-msp/", "d": "obrashchenie-v-gosorgan"}, {"id": "q_imushchestvennaya-podderzhka-msp", "c": "sup", "q": "Можно ли малому бизнесу получить госимущество в безвозмездное пользование?", "k": "можно ли малому бизнесу получить госимущество в безвозмездное пользование? да, законодательством могут быть предусмотрены меры имущественной поддержки мсп: безвозмездное пользование госимуществом (здания, помещения, оборудование и т.п.), понижающие коэффициенты к ставкам арендной платы и другие. конкретные условия определяют отдельные акты.", "a": "Да, законодательством могут быть предусмотрены меры имущественной поддержки МСП: безвозмездное пользование госимуществом (здания, помещения, оборудование и т.п.), понижающие коэффициенты к ставкам арендной платы и другие. Конкретные условия определяют отдельные акты.<br><br><b>Пошагово:</b><ol><li>Найдите свободное госимущество у исполкома или балансодержателя.</li><li>Уточните, какие меры поддержки действуют для вашего региона и деятельности.</li><li>Направьте письменный запрос владельцу имущества или в исполком.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 01.07.2010 № 148-З «О поддержке малого и среднего предпринимательства», ст. 12", "q": "Для субъектов малого и среднего предпринимательства законодательством могут быть предусмотрены меры имущественной поддержки в виде: предоставления в безвозмездное пользование находящихся в государственной собственности … капитальных строений (зданий, сооружений), изолированных помещений … машин, оборудования, транспортных средств; …", "u": "https://pravo.by/document/?guid=3871&p0=h11000148"}], "u": "/q/imushchestvennaya-podderzhka-msp/", "d": "obrashchenie-v-gosorgan"}, {"id": "q_kak-uchastvovat-v-goszakupkah", "c": "zak", "q": "Как малому бизнесу начать участвовать в госзакупках?", "k": "как малому бизнесу начать участвовать в госзакупках? участником признаётся юрлицо, ип или физлицо, подавшее предложение по процедуре. для электронных процедур нужна аккредитация на электронной торговой площадке (не менее чем на три года). закон № 148-з гарантирует субъектам мсп возможность участия в госзакупках.", "a": "Участником признаётся юрлицо, ИП или физлицо, подавшее предложение по процедуре. Для электронных процедур нужна аккредитация на электронной торговой площадке (не менее чем на три года). Закон № 148-З гарантирует субъектам МСП возможность участия в госзакупках.<br><br><b>Пошагово:</b><ol><li>Получите ЭЦП и пройдите аккредитацию на электронной торговой площадке.</li><li>Найдите подходящие закупки на официальном сайте госзакупок.</li><li>Проверьте требования к участникам (ст. 16 Закона № 419-З), включая отсутствие налоговой задолженности.</li><li>Подготовьте и подайте предложение в срок.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 13.07.2012 № 419-З «О государственных закупках товаров (работ, услуг)», п. 1 ст. 16", "q": "Участником признается юридическое или физическое лицо, в том числе индивидуальный предприниматель: представившее предложение, – в случае проведения открытого конкурса, закрытого конкурса, электронного аукциона, процедуры запроса ценовых предложений; …", "u": "https://pravo.by/document/?guid=3871&p0=h11200419"}, {"t": "Закон РБ от 13.07.2012 № 419-З «О государственных закупках товаров (работ, услуг)», п. 2 ст. 20", "q": "Аккредитация на электронной торговой площадке осуществляется оператором электронной торговой площадки на срок не менее трех лет в порядке, установленном Советом Министров Республики Беларусь.", "u": "https://pravo.by/document/?guid=3871&p0=h11200419"}, {"t": "Закон РБ от 01.07.2010 № 148-З «О поддержке малого и среднего предпринимательства», ст. 14", "q": "Субъектам малого и среднего предпринимательства гарантируется предоставление возможности участия в процедурах государственных закупок товаров (работ, услуг).", "u": "https://pravo.by/document/?guid=3871&p0=h11000148"}], "u": "/q/kak-uchastvovat-v-goszakupkah/", "d": null}, {"id": "q_kto-mozhet-perejti-na-usn", "c": "tax", "q": "Кто может перейти на упрощёнку (УСН) в Беларуси?", "k": "кто может перейти на упрощёнку (усн) в беларуси? перейти на усн с нового года вправе организации, у которых средняя численность за первые 9 месяцев предыдущего года не больше 50 человек, а валовая выручка за эти 9 месяцев — не более 2 800 000 рублей. есть ограничения по видам деятельности (ст. 324 нк). лимиты проверяйте в действующей редакции — они могут меняться.", "a": "Перейти на УСН с нового года вправе организации, у которых средняя численность за первые 9 месяцев предыдущего года не больше 50 человек, а валовая выручка за эти 9 месяцев — не более 2 800 000 рублей. Есть ограничения по видам деятельности (ст. 324 НК). Лимиты проверяйте в действующей редакции — они могут меняться.<br><br><b>Пошагово:</b><ol><li>Посчитайте среднюю численность и выручку за январь–сентябрь.</li><li>Сверьте вашу деятельность со списком ограничений ст. 324 НК.</li><li>Подайте уведомление о переходе в порядке ст. 327 НК.</li><li>Сравните налоговую нагрузку на УСН и общем порядке с бухгалтером.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Налоговый кодекс РБ (Особенная часть) от 29.12.2009 № 71-З, п. 2 ст. 327", "q": "Перейти на применение упрощенной системы вправе организации, у которых численность работников организации в среднем за первые девять месяцев года, предшествующего календарному году, в котором они претендуют начать применение упрощенной системы, не превышает 50 человек и валовая выручка нарастающим итогом за эти девять месяцев составляет не более 2 800 000 белорусских рублей.", "u": "https://pravo.by/document/?guid=3871&p0=hk0900071"}], "u": "/q/kto-mozhet-perejti-na-usn/", "d": null}, {"id": "q_kto-otnositsya-k-msp", "c": "sup", "q": "Кто относится к малому и среднему бизнесу в Беларуси?", "k": "кто относится к малому и среднему бизнесу в беларуси? к малому бизнесу относятся ип и коммерческие организации со средней численностью работников за календарный год до 100 человек включительно, к среднему — от 101 до 250 человек. критерии установлены ст. 3 закона № 148-з.", "a": "К малому бизнесу относятся ИП и коммерческие организации со средней численностью работников за календарный год до 100 человек включительно, к среднему — от 101 до 250 человек. Критерии установлены ст. 3 Закона № 148-З.<br><br><b>Пошагово:</b><ol><li>Определите среднюю численность работников за календарный год.</li><li>Сопоставьте с критериями ст. 3 Закона № 148-З.</li><li>Проверьте сведения о себе в Реестре субъектов МСП (ведёт МНС).</li><li>Используйте статус для участия в программах поддержки.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 01.07.2010 № 148-З «О поддержке малого и среднего предпринимательства», ст. 3", "q": "малые организации – зарегистрированные в Республике Беларусь коммерческие организации со средней численностью работников за календарный год до 100 человек включительно.", "u": "https://pravo.by/document/?guid=3871&p0=h11000148"}], "u": "/q/kto-otnositsya-k-msp/", "d": null}, {"id": "q_nds-0-pri-eksporte-v-rossiyu", "c": "ved", "q": "Как подтвердить НДС 0 % при экспорте товаров в Россию?", "k": "как подтвердить ндс 0 % при экспорте товаров в россию? при вывозе товаров в страны еаэс (в т.ч. в россию) ставка ндс 0 % подтверждается договором (контрактом), транспортными (товаросопроводительными) документами и заявлением о ввозе товаров и уплате косвенных налогов (или его электронным аналогом).", "a": "При вывозе товаров в страны ЕАЭС (в т.ч. в Россию) ставка НДС 0 % подтверждается договором (контрактом), транспортными (товаросопроводительными) документами и заявлением о ввозе товаров и уплате косвенных налогов (или его электронным аналогом).<br><br><b>Пошагово:</b><ol><li>Заключите внешнеторговый контракт.</li><li>Оформите транспортные и товаросопроводительные документы (CMR, ТТН и т.п.).</li><li>Получите от покупателя заявление о ввозе товаров с отметкой налогового органа России.</li><li>Храните пакет документов и соблюдайте сроки подтверждения по ст. 124 НК.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Налоговый кодекс РБ (Особенная часть) от 29.12.2009 № 71-З, ст. 124", "q": "1.1. договора (контракта), на основании которого осуществляется реализация товаров; 1.2. транспортных (товаросопроводительных) документов … 1.3. заявления о ввозе товаров и уплате косвенных налогов …", "u": "https://pravo.by/document/?guid=3871&p0=hk0900071"}], "u": "/q/nds-0-pri-eksporte-v-rossiyu/", "d": null}, {"id": "q_nds-pri-importe-iz-rossii", "c": "ved", "q": "Кто взимает НДС при ввозе товаров из России?", "k": "кто взимает ндс при ввозе товаров из россии? при ввозе товаров из государств еаэс (в том числе россии) ндс взимают не таможенные, а налоговые органы — по правилам нк и права еаэс (кроме процедур свободной таможенной зоны и свободного склада).", "a": "При ввозе товаров из государств ЕАЭС (в том числе России) НДС взимают не таможенные, а налоговые органы — по правилам НК и права ЕАЭС (кроме процедур свободной таможенной зоны и свободного склада).<br><br><b>Пошагово:</b><ol><li>Примите товары на учёт.</li><li>Подготовьте декларацию по косвенным налогам при импорте из ЕАЭС и заявление о ввозе.</li><li>Уплатите НДС в сроки, установленные НК.</li><li>Передайте заявление с отметкой инспекции поставщику для подтверждения его нулевой ставки.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Налоговый кодекс РБ (Особенная часть) от 29.12.2009 № 71-З, п. 1 ст. 139", "q": "При ввозе товаров на территорию Республики Беларусь с территории государств – членов Евразийского экономического союза взимание налога на добавленную стоимость осуществляют налоговые органы в соответствии с настоящим Кодексом и (или) международными договорами Республики Беларусь, составляющими право Евразийского экономического союза …", "u": "https://pravo.by/document/?guid=3871&p0=hk0900071"}], "u": "/q/nds-pri-importe-iz-rossii/", "d": null}, {"id": "q_neustojka-po-dogovoru", "c": "dog", "q": "Что такое неустойка и нужно ли доказывать убытки?", "k": "что такое неустойка и нужно ли доказывать убытки? неустойка (штраф, пеня) — сумма, которую должник обязан уплатить при неисполнении или просрочке. по требованию о неустойке кредитор не обязан доказывать убытки, но не вправе её требовать, если должник не несёт ответственности за нарушение.", "a": "Неустойка (штраф, пеня) — сумма, которую должник обязан уплатить при неисполнении или просрочке. По требованию о неустойке кредитор не обязан доказывать убытки, но не вправе её требовать, если должник не несёт ответственности за нарушение.<br><br><b>Пошагово:</b><ol><li>Найдите в договоре условие о неустойке и её размер.</li><li>Рассчитайте сумму за период нарушения.</li><li>Включите требование в претензию.</li><li>Если неустойки в договоре нет, проверьте законодательную неустойку и проценты по ст. 366 ГК.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, п. 1 ст. 311", "q": "Неустойкой (штрафом, пеней) признается определенная законодательством или договором денежная сумма, которую должник обязан уплатить кредитору … в случае неисполнения или ненадлежащего исполнения обязательства, в частности в случае просрочки исполнения. По требованию об уплате неустойки кредитор не обязан доказывать причинение ему убытков.", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}], "u": "/q/neustojka-po-dogovoru/", "d": "pretenziya-o-vzyskanii-dolga"}, {"id": "q_obrashchenie-yurlica-v-gosorgan", "c": "np", "q": "Как организации правильно написать обращение в госорган и в какой срок ждать ответ?", "k": "как организации правильно написать обращение в госорган и в какой срок ждать ответ? письменное обращение юрлица должно содержать адресата, полное наименование и место нахождения организации, суть обращения, фио и личную подпись руководителя (уполномоченного лица). ответ — не позднее 15 дней, а при необходимости дополнительного изучения — не позднее месяца.", "a": "Письменное обращение юрлица должно содержать адресата, полное наименование и место нахождения организации, суть обращения, ФИО и личную подпись руководителя (уполномоченного лица). Ответ — не позднее 15 дней, а при необходимости дополнительного изучения — не позднее месяца.<br><br><b>Пошагово:</b><ol><li>Определите орган, к компетенции которого относится вопрос.</li><li>Изложите суть кратко и конкретно, приложите документы.</li><li>Подпишите у руководителя или уполномоченного лица.</li><li>Зарегистрируйте обращение и считайте срок со следующего дня после регистрации.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 18.07.2011 № 300-З «Об обращениях граждан и юридических лиц», п. 3 ст. 12", "q": "Письменные обращения юридических лиц должны содержать: наименование и (или) адрес организации либо должность и (или) фамилию, собственное имя, отчество (если таковое имеется) либо инициалы лица, которым направляется обращение; полное наименование юридического лица и его место нахождения; изложение сути обращения; фамилию, собственное имя, отчество (если таковое имеется) либо инициалы руководителя или лица, уполномоченного в установленном порядке подписывать обращения; личную подпись руководителя или лица, уполномоченного в установленном порядке подписывать обращения.", "u": "https://pravo.by/document/?guid=3871&p0=h11100300"}, {"t": "Закон РБ от 18.07.2011 № 300-З «Об обращениях граждан и юридических лиц», п. 3 ст. 17", "q": "Письменные обращения должны быть рассмотрены не позднее пятнадцати дней, а обращения, требующие дополнительного изучения и проверки, – не позднее одного месяца, если иной срок не установлен законодательными актами.", "u": "https://pravo.by/document/?guid=3871&p0=h11100300"}], "u": "/q/obrashchenie-yurlica-v-gosorgan/", "d": "obrashchenie-v-gosorgan"}, {"id": "q_obshchestvennoe-obsuzhdenie-npa", "c": "np", "q": "Как бизнесу участвовать в обсуждении проектов законов и Платформы бизнеса?", "k": "как бизнесу участвовать в обсуждении проектов законов и платформы бизнеса? проекты актов, влияющие на условия ведения бизнеса, выносятся на публичное обсуждение (в т.ч. на «правовом форуме беларуси») сроком не менее 10 календарных дней. предложения в национальную платформу бизнеса собирают бизнес-объединения — субъекты мсп вправе объединяться в ассоциации и союзы.", "a": "Проекты актов, влияющие на условия ведения бизнеса, выносятся на публичное обсуждение (в т.ч. на «Правовом форуме Беларуси») сроком не менее 10 календарных дней. Предложения в Национальную платформу бизнеса собирают бизнес-объединения — субъекты МСП вправе объединяться в ассоциации и союзы.<br><br><b>Пошагово:</b><ol><li>Следите за проектами на forumpravo.by и сайтах госорганов.</li><li>Подайте замечания в срок публичного обсуждения.</li><li>Передайте проблемные вопросы в свою бизнес-ассоциацию для Платформы.</li><li>Для официальной позиции направьте письменное обращение в госорган.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 17.07.2018 № 130-З «О нормативных правовых актах», ст. 7", "q": "Срок публичного обсуждения проектов нормативных правовых актов определяется организатором публичного обсуждения … и составляет не менее 10 календарных дней.", "u": "https://pravo.by/document/?guid=3871&p0=h11800130"}, {"t": "Закон РБ от 01.07.2010 № 148-З «О поддержке малого и среднего предпринимательства», ст. 18", "q": "Субъекты малого и среднего предпринимательства в целях обеспечения наиболее благоприятных условий для развития и поддержки предпринимательства могут создавать объединения (ассоциации и союзы) …", "u": "https://pravo.by/document/?guid=3871&p0=h11000148"}], "u": "/q/obshchestvennoe-obsuzhdenie-npa/", "d": "obrashchenie-v-gosorgan"}, {"id": "q_obzhalovanie-rezultatov-proverki", "c": "chk", "q": "Как обжаловать решение по результатам проверки?", "k": "как обжаловать решение по результатам проверки? решение по акту проверки, требование (предписание) и действия проверяющих можно обжаловать в вышестоящий орган или вышестоящему должностному лицу в течение 30 календарных дней. жалоба рассматривается в месячный срок.", "a": "Решение по акту проверки, требование (предписание) и действия проверяющих можно обжаловать в вышестоящий орган или вышестоящему должностному лицу в течение 30 календарных дней. Жалоба рассматривается в месячный срок.<br><br><b>Пошагово:</b><ol><li>Определите, что именно обжалуете: решение, требование или действия.</li><li>Посчитайте 30 календарных дней со дня вынесения решения (совершения действия).</li><li>Направьте жалобу в вышестоящий орган с приложением документов.</li><li>При отказе рассмотрите судебный порядок вместе с юристом.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Указ Президента РБ от 06.06.2025 № 227 «О повышении эффективности контрольной (надзорной) деятельности» и утверждённое им Положение, пп. 85–87 Положения", "q": "… может быть подана в вышестоящий контролирующий (надзорный) орган, вышестоящему должностному лицу, которому проверяющие непосредственно подчинены, в течение 30 календарных дней со дня их вынесения (совершения).", "u": "https://pravo.by/document/?guid=3871&p0=P32500227"}], "u": "/q/obzhalovanie-rezultatov-proverki/", "d": null}, {"id": "q_odnostoronnij-otkaz-ot-dogovora", "c": "dog", "q": "Можно ли в одностороннем порядке отказаться от договора?", "k": "можно ли в одностороннем порядке отказаться от договора? односторонний отказ допускается, только если это предусмотрено законодательством или договором. он оформляется уведомлением другой стороны в той же форме, что и договор; договор прекращается с момента получения уведомления, если иное не установлено.", "a": "Односторонний отказ допускается, только если это предусмотрено законодательством или договором. Он оформляется уведомлением другой стороны в той же форме, что и договор; договор прекращается с момента получения уведомления, если иное не установлено.<br><br><b>Пошагово:</b><ol><li>Найдите в договоре или законе основание для одностороннего отказа.</li><li>Проверьте условия: сроки уведомления, компенсации.</li><li>Составьте уведомление в той же форме, что и договор (шаблон ниже).</li><li>Направьте его так, чтобы можно было подтвердить получение.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, ст. 291", "q": "Односторонний отказ от исполнения обязательства и одностороннее изменение его условий не допускаются, если иное не вытекает из законодательства или договора.", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}, {"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, п. 1 ст. 420¹", "q": "Предоставленное настоящим Кодексом, иными актами законодательства или договором право на односторонний отказ от договора (исполнения договора) может быть осуществлено управомоченной стороной путем уведомления другой стороны об отказе от договора (исполнения договора), оформляемого в той же форме, что и договор, если из законодательства или соглашения сторон не вытекает иное. Договор прекращается с момента получения такого уведомления …", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}], "u": "/q/odnostoronnij-otkaz-ot-dogovora/", "d": "uvedomlenie-ob-otkaze-ot-dogovora"}, {"id": "q_prava-pri-proverke", "c": "chk", "q": "Какие права есть у бизнеса во время проверки?", "k": "какие права есть у бизнеса во время проверки? проверяемый вправе узнать, почему его включили в план выборочных проверок, требовать служебное удостоверение и предписание, не допускать проверяющих без предписания и не выполнять требования за пределами предмета проверки. права перечислены в п. 14 положения к указу № 227.", "a": "Проверяемый вправе узнать, почему его включили в план выборочных проверок, требовать служебное удостоверение и предписание, не допускать проверяющих без предписания и не выполнять требования за пределами предмета проверки. Права перечислены в п. 14 Положения к Указу № 227.<br><br><b>Пошагово:</b><ol><li>Попросите предъявить удостоверение и предписание и сверьте ФИО, вопросы и сроки.</li><li>Запросите основания включения в план выборочных проверок.</li><li>Ведите учёт переданных проверяющим документов (опись).</li><li>Требования вне предмета проверки фиксируйте и оспаривайте письменно.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Указ Президента РБ от 06.06.2025 № 227 «О повышении эффективности контрольной (надзорной) деятельности» и утверждённое им Положение, п. 14 Положения", "q": "получать от контролирующих (надзорных) органов информацию об основаниях включения проверки в план выборочных проверок; требовать от проверяющего предъявления служебного удостоверения и предписания на проведение проверки; …", "u": "https://pravo.by/document/?guid=3871&p0=P32500227"}], "u": "/q/prava-pri-proverke/", "d": null}, {"id": "q_pravo-dogovora-s-rossijskoj-kompaniej", "c": "ved", "q": "Какое право применять в договоре с российской компанией?", "k": "какое право применять в договоре с российской компанией? стороны внешнеторгового договора могут сами выбрать применимое право — при заключении договора или позднее. выбор должен быть прямо выражен или явно вытекать из условий договора.", "a": "Стороны внешнеторгового договора могут сами выбрать применимое право — при заключении договора или позднее. Выбор должен быть прямо выражен или явно вытекать из условий договора.<br><br><b>Пошагово:</b><ol><li>Решите, право какой страны удобнее для вас (белорусское или российское).</li><li>Пропишите в договоре прямую оговорку о применимом праве.</li><li>Отдельно согласуйте порядок разрешения споров (суд, арбитраж).</li><li>Проверьте договор у юриста до подписания.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, пп. 1–2 ст. 1124", "q": "1. Стороны договора могут при заключении договора или в последующем выбрать по соглашению между собой право, которое подлежит применению к этому договору. 2. Соглашение сторон договора о выборе подлежащего применению права должно быть прямо выражено или должно явно вытекать из условий договора либо совокупности обстоятельств дела.", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}], "u": "/q/pravo-dogovora-s-rossijskoj-kompaniej/", "d": null}, {"id": "q_pretenziya-o-vzyskanii-dolga", "c": "dog", "q": "Как составить претензию о взыскании долга с контрагента?", "k": "как составить претензию о взыскании долга с контрагента? претензия — письменное требование погасить долг в срок до обращения в суд. укажите основание долга (договор, акты, накладные), сумму, проценты или неустойку и срок добровольной оплаты. обязательна ли претензия перед иском, зависит от договора и закона — проверьте это.", "a": "Претензия — письменное требование погасить долг в срок до обращения в суд. Укажите основание долга (договор, акты, накладные), сумму, проценты или неустойку и срок добровольной оплаты. Обязательна ли претензия перед иском, зависит от договора и закона — проверьте это.<br><br><b>Пошагово:</b><ol><li>Соберите договор, акты, накладные, акт сверки.</li><li>Рассчитайте основной долг, неустойку по договору или проценты по ст. 366 ГК.</li><li>Составьте претензию (используйте шаблон) и установите срок оплаты.</li><li>Направьте заказным письмом с уведомлением или вручите под роспись.</li><li>При отказе — исполнительная надпись нотариуса или суд (уточните у юриста).</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, ст. 290", "q": "Обязательства должны исполняться надлежащим образом в соответствии с условиями обязательства и требованиями законодательства …", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}, {"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, п. 1 ст. 364", "q": "Должник обязан возместить кредитору убытки, причиненные неисполнением или ненадлежащим исполнением обязательства.", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}], "u": "/q/pretenziya-o-vzyskanii-dolga/", "d": "pretenziya-o-vzyskanii-dolga"}, {"id": "q_procenty-za-prosrochku-oplaty", "c": "dog", "q": "Какие проценты можно взыскать за просрочку оплаты?", "k": "какие проценты можно взыскать за просрочку оплаты? за неправомерное удержание денег или иную просрочку оплаты подлежат уплате проценты по ст. 366 гк. их размер определяется ставкой рефинансирования национального банка на день исполнения обязательства (при взыскании в суде — на день вынесения решения).", "a": "За неправомерное удержание денег или иную просрочку оплаты подлежат уплате проценты по ст. 366 ГК. Их размер определяется ставкой рефинансирования Национального банка на день исполнения обязательства (при взыскании в суде — на день вынесения решения).<br><br><b>Пошагово:</b><ol><li>Определите дату, с которой началась просрочка.</li><li>Уточните ставку рефинансирования Нацбанка на нужную дату.</li><li>Рассчитайте проценты по дням просрочки.</li><li>Проверьте, нет ли в договоре неустойки — соотношение неустойки и процентов уточните у юриста.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, п. 1 ст. 366", "q": "За пользование чужими денежными средствами вследствие их неправомерного удержания, уклонения от их возврата, иной просрочки в их уплате либо неосновательного получения или сбережения за счет другого лица подлежат уплате проценты на сумму этих средств. Размер процентов определяется ставкой рефинансирования Национального банка на день исполнения денежного обязательства …", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}], "u": "/q/procenty-za-prosrochku-oplaty/", "d": "pretenziya-o-vzyskanii-dolga"}, {"id": "q_proverki-novyh-organizacij", "c": "chk", "q": "Можно ли проверять новую организацию или ИП в первые два года?", "k": "можно ли проверять новую организацию или ип в первые два года? по общему правилу проверки запрещены в течение двух лет со дня государственной регистрации организации (кроме созданных при реорганизации) или ип. исключения — случаи, перечисленные в части второй того же пункта (например, отдельные внеплановые проверки).", "a": "По общему правилу проверки запрещены в течение двух лет со дня государственной регистрации организации (кроме созданных при реорганизации) или ИП. Исключения — случаи, перечисленные в части второй того же пункта (например, отдельные внеплановые проверки).<br><br><b>Пошагово:</b><ol><li>Проверьте дату госрегистрации в свидетельстве или ЕГР.</li><li>Если вам назначили проверку в первые два года — уточните её вид и основание в предписании.</li><li>Сверьте основание с исключениями п. 34 Положения.</li><li>При сомнениях запросите разъяснение у проверяющего органа или юриста.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Указ Президента РБ от 06.06.2025 № 227 «О повышении эффективности контрольной (надзорной) деятельности» и утверждённое им Положение, п. 34 Положения", "q": "Запрещается, за исключением случаев, предусмотренных в части второй настоящего пункта, проведение проверок в течение двух лет со дня: государственной регистрации – организаций (кроме созданных в порядке реорганизации), индивидуальных предпринимателей; …", "u": "https://pravo.by/document/?guid=3871&p0=P32500227"}], "u": "/q/proverki-novyh-organizacij/", "d": null}, {"id": "q_razyasnenie-nalogovoj", "c": "tax", "q": "Как получить официальное разъяснение налоговой?", "k": "как получить официальное разъяснение налоговой? плательщик вправе получать от налоговых органов разъяснения по применению налогового законодательства, а налоговые органы обязаны их давать. запрос юрлица оформляется как письменное обращение по закону № 300-з.", "a": "Плательщик вправе получать от налоговых органов разъяснения по применению налогового законодательства, а налоговые органы обязаны их давать. Запрос юрлица оформляется как письменное обращение по Закону № 300-З.<br><br><b>Пошагово:</b><ol><li>Сформулируйте конкретный вопрос и опишите ситуацию (операция, даты, суммы).</li><li>Укажите полное наименование, УНП, адрес и ФИО руководителя.</li><li>Направьте запрос в свою инспекцию МНС (письменно или электронно).</li><li>Ответ на обращение по общему правилу — до 15 дней, при доп. изучении — до 1 месяца.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Налоговый кодекс РБ (Общая часть) от 19.12.2002 № 166-З, подп. 1.1 п. 1 ст. 21", "q": "1.1. получать от налоговых органов и других уполномоченных государственных органов разъяснения по вопросам применения актов налогового законодательства;", "u": "https://pravo.by/document/?guid=3871&p0=hk0200166"}, {"t": "Налоговый кодекс РБ (Общая часть) от 19.12.2002 № 166-З, подп. 1.8 п. 1 ст. 108", "q": "1.8. давать разъяснения плательщикам по вопросам применения налогового законодательства …", "u": "https://pravo.by/document/?guid=3871&p0=hk0200166"}, {"t": "Закон РБ от 18.07.2011 № 300-З «Об обращениях граждан и юридических лиц», п. 3 ст. 17", "q": "Письменные обращения должны быть рассмотрены не позднее пятнадцати дней, а обращения, требующие дополнительного изучения и проверки, – не позднее одного месяца, если иной срок не установлен законодательными актами.", "u": "https://pravo.by/document/?guid=3871&p0=h11100300"}], "u": "/q/razyasnenie-nalogovoj/", "d": "zapros-razyasneniya-nalogovaya"}, {"id": "q_reestr-subektov-msp", "c": "sup", "q": "Что такое Реестр субъектов МСП и кто его ведёт?", "k": "что такое реестр субъектов мсп и кто его ведёт? реестр субъектов малого и среднего предпринимательства — электронная база данных о лицах, соответствующих критериям мсп. его формирует и ведёт министерство по налогам и сборам; порядок определяет совет министров.", "a": "Реестр субъектов малого и среднего предпринимательства — электронная база данных о лицах, соответствующих критериям МСП. Его формирует и ведёт Министерство по налогам и сборам; порядок определяет Совет Министров.<br><br><b>Пошагово:</b><ol><li>Проверьте, соответствуете ли вы критериям ст. 3 Закона № 148-З.</li><li>Уточните наличие сведений о себе в Реестре через МНС.</li><li>При ошибке обратитесь в налоговый орган с письменным обращением.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 01.07.2010 № 148-З «О поддержке малого и среднего предпринимательства», ст. 3¹", "q": "Реестр представляет собой электронную базу данных, содержащую сведения о субъектах малого и среднего предпринимательства Республики Беларусь. Реестр формируется и ведется Министерством по налогам и сборам.", "u": "https://pravo.by/document/?guid=3871&p0=h11000148"}], "u": "/q/reestr-subektov-msp/", "d": "obrashchenie-v-gosorgan"}, {"id": "q_srok-iskovoj-davnosti", "c": "dog", "q": "Сколько лет можно взыскать долг (срок исковой давности)?", "k": "сколько лет можно взыскать долг (срок исковой давности)? общий срок исковой давности — три года. по обязательствам с определённым сроком исполнения он начинает течь по окончании этого срока. для отдельных требований могут быть установлены специальные сроки.", "a": "Общий срок исковой давности — три года. По обязательствам с определённым сроком исполнения он начинает течь по окончании этого срока. Для отдельных требований могут быть установлены специальные сроки.<br><br><b>Пошагово:</b><ol><li>Определите дату, когда оплата должна была поступить.</li><li>Отсчитайте три года с этой даты.</li><li>Проверьте, нет ли специального срока для вашего вида требования.</li><li>Не затягивайте: давность применяется судом по заявлению стороны спора.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, ст. 197", "q": "Общий срок исковой давности устанавливается в три года.", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}, {"t": "Гражданский кодекс РБ от 07.12.1998 № 218-З, п. 2 ст. 201", "q": "По обязательствам с определенным сроком исполнения течение исковой давности начинается по окончании срока исполнения.", "u": "https://pravo.by/document/?guid=3871&p0=hk9800218"}], "u": "/q/srok-iskovoj-davnosti/", "d": "pretenziya-o-vzyskanii-dolga"}, {"id": "q_srok-proverki", "c": "chk", "q": "Сколько может длиться проверка организации или ИП?", "k": "сколько может длиться проверка организации или ип? выборочная или внеплановая проверка организации — не более 30 рабочих дней, ип — не более 15 рабочих дней. для оперативных тематических и дополнительных проверок действуют отдельные сроки (дополнительная — до 10 рабочих дней).", "a": "Выборочная или внеплановая проверка организации — не более 30 рабочих дней, ИП — не более 15 рабочих дней. Для оперативных тематических и дополнительных проверок действуют отдельные сроки (дополнительная — до 10 рабочих дней).<br><br><b>Пошагово:</b><ol><li>Посмотрите срок, указанный в предписании на проведение проверки.</li><li>Считайте рабочие дни с даты начала, указанной в предписании.</li><li>Если проверка затягивается сверх предельного срока, зафиксируйте это письменно.</li><li>При нарушении сроков используйте право на обжалование действий проверяющих.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Указ Президента РБ от 06.06.2025 № 227 «О повышении эффективности контрольной (надзорной) деятельности» и утверждённое им Положение, п. 37 Положения", "q": "Срок проведения проверки, за исключением внеплановой тематической оперативной и дополнительной проверок, не может превышать при проведении проверок: индивидуальных предпринимателей … – 15 рабочих дней; иных проверяемых субъектов – 30 рабочих дней.", "u": "https://pravo.by/document/?guid=3871&p0=P32500227"}, {"t": "Указ Президента РБ от 06.06.2025 № 227 «О повышении эффективности контрольной (надзорной) деятельности» и утверждённое им Положение, п. 37 Положения", "q": "Срок проведения дополнительной проверки не может превышать 10 рабочих дней.", "u": "https://pravo.by/document/?guid=3871&p0=P32500227"}], "u": "/q/srok-proverki/", "d": null}, {"id": "q_stavka-usn", "c": "tax", "q": "Какая ставка налога при упрощёнке и как часто отчитываться?", "k": "какая ставка налога при упрощёнке и как часто отчитываться? ставка налога при упрощённой системе — 6 %. налоговый период — календарный год, отчётный — квартал; налог считается нарастающим итогом с начала года.", "a": "Ставка налога при упрощённой системе — 6 %. Налоговый период — календарный год, отчётный — квартал; налог считается нарастающим итогом с начала года.<br><br><b>Пошагово:</b><ol><li>Определите валовую выручку за квартал нарастающим итогом.</li><li>Умножьте налоговую базу на ставку 6 %.</li><li>Подайте декларацию и уплатите налог в сроки, установленные НК.</li><li>Проверьте, не изменились ли ставки в текущем году.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Налоговый кодекс РБ (Особенная часть) от 29.12.2009 № 71-З, ст. 329", "q": "Ставка налога при упрощенной системе устанавливается в размере шесть (6) процентов.", "u": "https://pravo.by/document/?guid=3871&p0=hk0900071"}, {"t": "Налоговый кодекс РБ (Особенная часть) от 29.12.2009 № 71-З, ст. 330", "q": "1. Налоговым периодом налога при упрощенной системе признается календарный год. 2. Отчетным периодом по налогу при упрощенной системе признается календарный квартал.", "u": "https://pravo.by/document/?guid=3871&p0=hk0900071"}], "u": "/q/stavka-usn/", "d": null}, {"id": "q_ukaz-227-formy-kontrolya", "c": "chk", "q": "Что изменил Указ № 227 о проверках с 2026 года?", "k": "что изменил указ № 227 о проверках с 2026 года? с 1 января 2026 г. порядок контроля определяет указ № 227 от 06.06.2025 (указ № 510 утратил силу). государственный контроль ведут только контролирующие органы в формах выборочных и внеплановых проверок, мероприятий технического характера и иных форм, а органы обязаны применять меры профилактики.", "a": "С 1 января 2026 г. порядок контроля определяет Указ № 227 от 06.06.2025 (Указ № 510 утратил силу). Государственный контроль ведут только контролирующие органы в формах выборочных и внеплановых проверок, мероприятий технического характера и иных форм, а органы обязаны применять меры профилактики.<br><br><b>Пошагово:</b><ol><li>Узнайте, какие органы контролируют вашу сферу.</li><li>Следите за планом выборочных проверок на сайте КГК.</li><li>Используйте профилактические мероприятия (рекомендации, чек-листы) для самопроверки.</li><li>Изучите права и обязанности проверяемого в Положении.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Указ Президента РБ от 06.06.2025 № 227 «О повышении эффективности контрольной (надзорной) деятельности» и утверждённое им Положение, п. 1.1 Указа", "q": "государственный контроль (надзор) осуществляется только контролирующими (надзорными) органами в следующих формах: выборочные проверки; внеплановые проверки; мероприятия технического (технологического, поверочного) характера; …", "u": "https://pravo.by/document/?guid=3871&p0=P32500227"}], "u": "/q/ukaz-227-formy-kontrolya/", "d": null}, {"id": "q_uvedomlenie-o-vyborochnoj-proverke", "c": "chk", "q": "За сколько дней предупреждают о выборочной проверке?", "k": "за сколько дней предупреждают о выборочной проверке? о выборочной проверке организацию или ип должны письменно уведомить не позднее чем за 10 рабочих дней до её начала. порядок установлен положением, утверждённым указом № 227, который действует с 1 января 2026 г.", "a": "О выборочной проверке организацию или ИП должны письменно уведомить не позднее чем за 10 рабочих дней до её начала. Порядок установлен Положением, утверждённым Указом № 227, который действует с 1 января 2026 г.<br><br><b>Пошагово:</b><ol><li>Проверьте, пришло ли письменное уведомление и сколько рабочих дней осталось до начала проверки.</li><li>Сверьте вопросы и проверяемый период, указанные в уведомлении.</li><li>Подготовьте документы за проверяемый период и назначьте ответственного.</li><li>В день начала проверки попросите предъявить служебное удостоверение и предписание.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Указ Президента РБ от 06.06.2025 № 227 «О повышении эффективности контрольной (надзорной) деятельности» и утверждённое им Положение, п. 29 Положения", "q": "О назначении выборочной проверки проверяемый субъект должен быть письменно уведомлен не позднее чем за 10 рабочих дней до начала ее проведения.", "u": "https://pravo.by/document/?guid=3871&p0=P32500227"}], "u": "/q/uvedomlenie-o-vyborochnoj-proverke/", "d": null}, {"id": "q_vozrazheniya-na-akt-proverki", "c": "chk", "q": "Как подать возражения на акт проверки и в какой срок?", "k": "как подать возражения на акт проверки и в какой срок? при несогласии с актом (справкой) проверки сделайте запись об этом перед подписью и не позднее 15 рабочих дней со дня вручения акта подайте письменные возражения в контролирующий орган. по возражениям в течение 15 рабочих дней готовится письменное заключение.", "a": "При несогласии с актом (справкой) проверки сделайте запись об этом перед подписью и не позднее 15 рабочих дней со дня вручения акта подайте письменные возражения в контролирующий орган. По возражениям в течение 15 рабочих дней готовится письменное заключение.<br><br><b>Пошагово:</b><ol><li>При подписании акта напишите перед подписью «С возражениями».</li><li>Отсчитайте 15 рабочих дней со дня вручения акта.</li><li>Подготовьте возражения по каждому пункту с документами-доказательствами.</li><li>Подайте возражения в орган, проводивший проверку, с отметкой о приёме или заказным письмом.</li><li>Дождитесь письменного заключения по возражениям.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Указ Президента РБ от 06.06.2025 № 227 «О повышении эффективности контрольной (надзорной) деятельности» и утверждённое им Положение, п. 80 Положения", "q": "При наличии возражений по акту (справке) проверки, в том числе промежуточному, проверяемый субъект или его представитель делает об этом запись перед своей подписью и не позднее 15 рабочих дней со дня вручения акта (справки) проверки, в том числе промежуточного, представляет в письменном виде возражения по его содержанию в контролирующий (надзорный) орган.", "u": "https://pravo.by/document/?guid=3871&p0=P32500227"}], "u": "/q/vozrazheniya-na-akt-proverki/", "d": "vozrazheniya-na-akt-proverki"}, {"id": "q_vozvrat-pereplaty-naloga", "c": "tax", "q": "Как вернуть или зачесть переплату налога?", "k": "как вернуть или зачесть переплату налога? излишне уплаченный налог, сбор или пени засчитываются или возвращаются по заявлению плательщика не позднее пяти лет со дня уплаты. как правило, возврат производится без процентов.", "a": "Излишне уплаченный налог, сбор или пени засчитываются или возвращаются по заявлению плательщика не позднее пяти лет со дня уплаты. Как правило, возврат производится без процентов.<br><br><b>Пошагово:</b><ol><li>Сверьте расчёты с инспекцией (акт сверки) и подтвердите переплату.</li><li>Решите: зачесть в счёт других платежей или вернуть на счёт.</li><li>Подайте заявление в инспекцию по установленной форме.</li><li>Следите за пятилетним сроком со дня уплаты.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Налоговый кодекс РБ (Общая часть) от 19.12.2002 № 166-З, ст. 66", "q": "Зачет или возврат излишне уплаченной суммы налога, сбора (пошлины), пеней производятся не позднее пяти лет со дня уплаты указанной суммы …", "u": "https://pravo.by/document/?guid=3871&p0=hk0200166"}], "u": "/q/vozvrat-pereplaty-naloga/", "d": null}, {"id": "q_zhaloba-na-zakazchika-goszakupki", "c": "zak", "q": "Как обжаловать действия заказчика в госзакупках?", "k": "как обжаловать действия заказчика в госзакупках? участник или иное лицо вправе подать жалобу в уполномоченный государственный орган по госзакупкам на действия, бездействие или решения заказчика (организатора), комиссии, биржи или оператора площадки. сроки подачи зависят от предмета жалобы (ст. 52 закона № 419-з) — они короткие.", "a": "Участник или иное лицо вправе подать жалобу в уполномоченный государственный орган по госзакупкам на действия, бездействие или решения заказчика (организатора), комиссии, биржи или оператора площадки. Сроки подачи зависят от предмета жалобы (ст. 52 Закона № 419-З) — они короткие.<br><br><b>Пошагово:</b><ol><li>Зафиксируйте нарушение (скриншоты, протоколы).</li><li>Определите срок подачи по ст. 52 Закона № 419-З.</li><li>Подготовьте жалобу с обоснованием и доказательствами.</li><li>Подайте её в уполномоченный орган по госзакупкам.</li></ol>", "s": ["Статья «Алеся-Юрист», нормы по pravo.by"], "L": [{"t": "Закон РБ от 13.07.2012 № 419-З «О государственных закупках товаров (работ, услуг)», п. 1 ст. 52", "q": "Участник либо иное юридическое или физическое лицо, в том числе индивидуальный предприниматель, вправе подать жалобу в уполномоченный государственный орган по государственным закупкам … на действия (бездействие) и (или) решения заказчика (организатора), комиссии и (или) ее членов, товарной биржи, оператора электронной торговой площадки в случае нарушения их прав и законных интересов.", "u": "https://pravo.by/document/?guid=3871&p0=h11200419"}], "u": "/q/zhaloba-na-zakazchika-goszakupki/", "d": null}];const seen=new Set(window.KB.map(k=>k.q));Q.forEach(k=>{if(!seen.has(k.q))window.KB.push(k)})})();
